/**
 * The Hugo adapter's GENERATED files — written by `node kit/build.mjs` (`npm run build`) from the kit's own
 * sources, so the Hugo markup and strings cannot drift from the reference; adapters/hugo/test/hugo.test.ts fails
 * when a committed copy differs from a fresh generation.
 *
 *   layouts/partials/consent-kit/banner.html  ← kit/templates/banner.html: a string placeholder {{key}} becomes
 *                                              {{ i18n "consentKit_key" }}, {{key|blocks}} a range over that
 *                                              string's lines (kit/build.mjs blocks() in Hugo), an adapter value
 *                                              ({{privacyUrl}}, {{imprintUrl}}, {{endpoint}}, {{site}}) the value of
 *                                              site.Params.consentKit validated by consent-kit/params.html
 *   i18n/<lang>.yaml                           ← kit/src/i18n/<lang>.json: the sample strings as consentKit_<key>
 */
import { ADAPTER_VALUES, BLOCK_CLASS, LANGS, bannerTemplate, replacePlaceholders, strings } from "../../kit/build.mjs";

/** The i18n id prefix of every kit string. */
export const PREFIX = "consentKit_";

/** The string keys of the reference strings (every language has the same keys; kit/test/build.test.ts). */
const stringKeys = () => Object.keys(strings(LANGS[0])).filter((key) => key !== "_note");

/** The Hugo partial of the markup: the template with Hugo actions in place of its placeholders. */
export function bannerPartial() {
  const keys = new Set(stringKeys());
  const ids = [];
  const markup = replacePlaceholders(bannerTemplate(), (key, filter) => {
    if (ADAPTER_VALUES.includes(key)) {
      if (filter !== undefined) throw new Error(`templates/banner.html: {{${key}|${filter}}}: an adapter value takes no filter`);
      return `{{ $ck.${key} }}`;
    }
    if (!keys.has(key)) throw new Error(`templates/banner.html: {{${key}}} is neither a string key nor an adapter value`);
    if (!ids.includes(PREFIX + key)) ids.push(PREFIX + key);
    if (filter === "blocks") {
      // blocks() of kit/build.mjs: split at "\n", spaces, tabs and carriage returns at the ends trimmed, empty lines
      // left out, one span per line, joined by one space; html/template escapes each part (no safeHTML)
      const shown = `$${key}Shown`;
      return (
        `{{ ${shown} := false }}{{ range split (i18n "${PREFIX}${key}") "\\n" }}{{ with trim . " \\t\\r" }}` +
        `{{ if ${shown} }} {{ end }}{{ ${shown} = true }}<span class="${BLOCK_CLASS}">{{ . }}</span>{{ end }}{{ end }}`
      );
    }
    return `{{ i18n "${PREFIX}${key}" }}`;
  });
  return [
    "{{- /* GENERATED by kit/build.mjs from kit/templates/banner.html: do not edit (adapters/hugo/README.md).",
    '  The first layer and the settings dialog, the FIRST thing in <body>: partial "consent-kit/banner.html" .',
    "  Strings: the i18n ids consentKit_<key>. This module's i18n/ holds samples; a site's own i18n with the same",
    "  ids wins, and a missing string fails the build. Values: site.Params.consentKit (privacyUrl, imprintUrl,",
    "  endpoint, site), validated by consent-kit/params.html. */ -}}",
    '{{- $ck := partialCached "consent-kit/params.html" . site.Language.Lang -}}',
    "{{- range slice",
    ...ids.map((id) => `  "${id}"`),
    "-}}",
    "  {{- if not (i18n .) -}}",
    '    {{- errorf "consent-kit: no string %q for the language %q (adapters/hugo/README.md, Your own texts)" . site.Language.Lang -}}',
    "  {{- end -}}",
    "{{- end -}}",
    markup,
  ].join("\n");
}

/** Every line break of a YAML 1.1 reader: LF, CR, NEL (U+0085), LS (U+2028), PS (U+2029). */
const LINE_BREAKS = new RegExp(`[${String.fromCharCode(0x0a, 0x0d, 0x85, 0x2028, 0x2029)}]`);
/** The three of them JSON leaves raw: NEL, LS, PS. */
const RAW_BREAKS = new RegExp(`[${String.fromCharCode(0x85, 0x2028, 0x2029)}]`, "g");

/** A YAML double-quoted scalar: JSON's escapes are YAML's; NEL, LS and PS escaped as well (four hex digits). */
export function yamlString(value, where) {
  // go-i18n reads a translation that contains the template delimiter as a Go template
  if (value.includes("{{")) throw new Error(`${where}: "{{" in a string — go-i18n would read it as a template`);
  return JSON.stringify(value).replace(RAW_BREAKS, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`);
}

/** A YAML comment line: the text must stay on it — after a line break, the rest would be read as YAML. */
export function yamlComment(text, where) {
  if (LINE_BREAKS.test(text)) throw new Error(`${where}: a line break in a YAML comment — the rest would be read as YAML`);
  return `# ${text}`;
}

/** The sample strings of a language as Hugo i18n entries. */
export function i18nFile(lang) {
  const s = strings(lang);
  const lines = [
    `# GENERATED by kit/build.mjs from kit/src/i18n/${lang}.json: do not edit (adapters/hugo/README.md).`,
    yamlComment(s._note, `kit/src/i18n/${lang}.json: _note`),
    `# A site's own i18n/${lang}.yaml entry with the same id wins.`,
  ];
  for (const key of stringKeys()) lines.push(`${PREFIX}${key}: ${yamlString(s[key], `kit/src/i18n/${lang}.json: ${key}`)}`);
  return lines.join("\n") + "\n";
}

/** Every generated file, by its path below adapters/hugo/. */
export function generate() {
  const files = { "layouts/partials/consent-kit/banner.html": bannerPartial() };
  for (const lang of LANGS) files[`i18n/${lang}.yaml`] = i18nFile(lang);
  return files;
}
